def simplified_lesk(word, sentence, senses):
    # senses: {의미: 사전 뜻풀이 문장}
    context = set(tokenize(sentence)) - {word}
    best, best_overlap = None, -1
    for sense, gloss in senses.items():
        # 문맥 단어와 뜻풀이 단어의 중첩 수
        overlap = len(context & set(tokenize(gloss)))
        if overlap > best_overlap:
            best, best_overlap = sense, overlap
    return best  # 가장 많이 겹치는 의미 선택
